tailwind.config = {
    darkMode: 'class',
    theme: {
        extend: {
            colors: {
                embers: {
                    base: '#2a3950',
                    indigo: '#41436A',
                    wine: '#984063',
                    coral: '#30c5ad',
                    peach: '#e98006',
                    white: '#ffffff'
                }
            }
        }
    }
};

head.b:skin:
* {
    box-sizing: border-box;
}

html {
    scroll-behavior: smooth;
}

body {
    margin: 0;
    padding: 0;
    background:
        radial-gradient(
            circle at 50% -10%,
            #41436A 0%,
            #2a3950 45%,
            #151d2a 100%
        );
    color: #ffffff;
    font-family: 'Noto Sans Devanagari', sans-serif;
    min-height: 100vh;
}

body, button, input {
    font-family: 'Noto Sans Devanagari', sans-serif;
}

button {
    -webkit-tap-highlight-color: transparent;
}

::-webkit-scrollbar {
    width: 7px;
}

::-webkit-scrollbar-track {
    background: #1a2332;
}

::-webkit-scrollbar-thumb {
    background: #41436A;
    border-radius: 10px;
}

::-webkit-scrollbar-thumb:hover {
    background: #e98006;
}

#Blog1, .blog-posts, .blog-pager, .blog-feeds, .post-outer, .widget {
    display: none !important;
}

.seo-crawler-indexing {
    position: absolute !important;
    width: 1px !important;
    height: 1px !important;
    padding: 0 !important;
    margin: -1px !important;
    overflow: hidden !important;
    clip: rect(0, 0, 0, 0) !important;
    white-space: nowrap !important;
    border: 0 !important;
}

.bhajasi-root {
    min-height: 100vh;
}

.bhajasi-app {
    min-height: 100vh;
    max-width: 760px;
    margin: auto;
    padding-bottom: 78px;
}

/* Header */
.bhajasi-header {
    position: sticky;
    top: 0;
    z-index: 50;
    background: rgba(42, 57, 80, 0.96);
    backdrop-filter: blur(14px);
    -webkit-backdrop-filter: blur(14px);
    border-bottom: 1px solid rgba(233, 128, 6, 0.25);
    padding: 9px 15px;
}

.bhajasi-brandline {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 10px;
}

.bhajasi-brand-container {
    display: flex;
    align-items: center;
    gap: 10px;
    min-width: 0;
}

.bhajasi-header-logo {
    width: 38px;
    height: 38px;
    min-width: 38px;
    min-height: 38px;
    object-fit: contain;
    border-radius: 50%;
    filter: drop-shadow(0 2px 5px rgba(0,0,0,0.3));
}

.bhajasi-brand-group {
    display: flex;
    flex-direction: column;
}

.bhajasi-brand-wrapper {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    line-height: 1;
}

.bhajasi-brand {
    margin: 0;
    font-family: 'Alkatra', cursive;
    font-size: 22px;
    line-height: 1.18;
    font-weight: 400;
    letter-spacing: 0.5px;
    white-space: nowrap;
    background: linear-gradient(135deg, #fbd52d 0%, #e98006 100%);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
}

.brand-domain {
    font-family: 'Noto Sans Devanagari', sans-serif;
    font-size: 11px;
    font-weight: 700;
    color: #ffffff;
    opacity: 0.9;
    letter-spacing: 0.5px;
    margin-bottom: 2px;
}

.bhajasi-tagline {
    color: #cbd5e1;
    font-size: 10.5px;
    margin-top: 2px;
    white-space: nowrap;
}

.bhajasi-action-group {
    display: flex;
    flex-direction: column;
    align-items: flex-end;
    gap: 4px;
}

.bhajasi-credit {
    color: #cbd5e1;
    font-size: 10px;
    font-weight: 600;
}

.bhajasi-social-btns {
    display: flex;
    align-items: center;
    gap: 6px;
}

.bhajasi-header-btn {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    padding: 3px 8px;
    border-radius: 6px;
    font-size: 10.5px;
    font-weight: 600;
    border: 1px solid rgba(233, 128, 6, 0.4);
    background: rgba(65, 67, 106, 0.7);
    color: #fbd52d;
    cursor: pointer;
    text-decoration: none;
    transition: all 0.2s ease;
}

.bhajasi-header-btn:hover {
    background: #e98006;
    color: #2a3950;
}

.bhajasi-whatsapp-btn {
    border-color: rgba(37, 211, 102, 0.35);
    background: rgba(37, 211, 102, 0.12);
    color: #25d366;
}

.bhajasi-whatsapp-btn:hover {
    background: #25d366;
    color: #ffffff;
}

.bhajasi-progress {
    height: 2.5px;
    background: #1a2332;
    margin: 8px -15px -9px;
}

.bhajasi-progress-bar {
    height: 100%;
    width: 0;
    background: linear-gradient(90deg, #fbd52d, #e98006);
    transition: width .25s ease;
}

.bhajasi-main {
    padding: 13px 16px 20px;
}

/* Sections */
.bhajasi-section {
    margin-bottom: 24px;
    border-radius: 18px;
    padding: 14px;
    border: 1px solid transparent;
}

.bhajasi-section-saints {
    background: rgba(30, 42, 60, 0.75);
    border-color: rgba(65, 67, 106, 0.95);
    box-shadow: 0 4px 18px rgba(0, 0, 0, 0.3);
}

.bhajasi-section-works {
    background: rgba(152, 64, 99, 0.24);
    border-color: rgba(152, 64, 99, 0.65);
}

.bhajasi-section-themes {
    background: rgba(48, 197, 173, 0.12);
    border-color: rgba(48, 197, 173, 0.45);
}

.bhajasi-section-title {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin: 2px 4px 12px;
}

.bhajasi-section-title h2,
.bhajasi-section-title h3 {
    margin: 0;
    font-family: 'Tiro Devanagari Marathi', serif;
    font-size: 20px;
    line-height: 1.3;
    font-weight: 700;
    letter-spacing: 0.02em;
}

/* Search */

/* Page navigation and global search overlay */
.bhajasi-page-nav{display:flex;gap:7px;overflow-x:auto;padding:2px 0 12px;margin-bottom:2px;scrollbar-width:none}
.bhajasi-page-nav::-webkit-scrollbar{display:none}
.bhajasi-nav-chip,.bhajasi-filter-chip{flex:0 0 auto;border:1px solid rgba(65,67,106,.9);background:rgba(26,35,50,.72);color:#cbd5e1;border-radius:999px;padding:7px 11px;font-size:11px;font-weight:600;cursor:pointer;white-space:nowrap}
.bhajasi-nav-chip:hover,.bhajasi-nav-chip.active,.bhajasi-filter-chip:hover,.bhajasi-filter-chip.active{color:#1a2332;background:linear-gradient(135deg,#fbd52d,#e98006);border-color:#e98006}
.bhajasi-filter-grid{display:flex;flex-wrap:wrap;gap:7px;margin:0 0 12px}
.bhajasi-category-note{font-size:11px;color:#94a3b8;line-height:1.55;margin:-3px 0 12px}
.bhajasi-floating-search{position:fixed;z-index:95;right:max(16px,calc((100vw - 760px)/2 + 16px));bottom:calc(78px + env(safe-area-inset-bottom) + 16px);width:52px;height:52px;border-radius:50%;border:1px solid rgba(233,128,6,.7);background:linear-gradient(145deg,#2a3950,#172233);color:#fbd52d;box-shadow:0 8px 28px rgba(0,0,0,.45);cursor:pointer;font-size:19px}
.bhajasi-search-overlay{position:fixed;inset:0;z-index:200;display:flex;align-items:flex-start;justify-content:center;padding:78px 14px 24px;background:rgba(8,13,22,.58);backdrop-filter:blur(8px);-webkit-backdrop-filter:blur(8px)}
.bhajasi-search-dialog{width:min(680px,100%);max-height:calc(100vh - 110px);overflow:hidden;border:1px solid rgba(233,128,6,.5);border-radius:18px;background:linear-gradient(160deg,#25344a,#141e2c);box-shadow:0 24px 70px rgba(0,0,0,.65)}
.bhajasi-global-search-head{display:flex;align-items:center;gap:8px;padding:14px;border-bottom:1px solid rgba(65,67,106,.55)}
.bhajasi-global-search-input{flex:1;min-width:0;background:#121b29;border:1px solid rgba(65,67,106,.95);border-radius:12px;color:#fff;padding:11px 13px;outline:none;font-size:14px}
.bhajasi-global-search-input:focus{border-color:#e98006;box-shadow:0 0 0 2px rgba(233,128,6,.15)}
.bhajasi-global-search-close{width:40px;height:40px;border:0;border-radius:10px;background:rgba(65,67,106,.55);color:#fff;cursor:pointer;font-size:17px}
.bhajasi-global-results{max-height:calc(100vh - 210px);overflow:auto;padding:8px}
.bhajasi-global-result{width:100%;display:block;text-align:left;border:0;border-bottom:1px solid rgba(65,67,106,.35);background:transparent;color:#fff;padding:11px 10px;cursor:pointer;border-radius:10px}
.bhajasi-global-result:hover{background:rgba(65,67,106,.38)}
.bhajasi-global-result-title{font-family:'Khand',sans-serif;font-size:17px;color:#fbd52d;font-weight:600}
.bhajasi-global-result-sub{font-size:11px;color:#cbd5e1;margin-top:2px;line-height:1.5}
.bhajasi-global-empty{padding:28px 16px;text-align:center;color:#94a3b8;font-size:13px}
.bhajasi-meaning{border-top:none!important}
.bhajasi-notify-bell{display:none!important}

.bhajasi-search-wrapper {
    position: relative;
    margin: 4px 0 19px;
}

.bhajasi-search-box {
    position: relative;
    display: flex;
    align-items: center;
}

.bhajasi-search-box input {
    width: 100%;
    background: rgba(26, 35, 50, 0.95);
    border: 1px solid rgba(65, 67, 106, 0.8);
    border-radius: 12px;
    padding: 11px 40px 11px 14px;
    color: #ffffff;
    outline: none;
    font-size: 14px;
    transition: border-color .2s;
}

.bhajasi-search-box input:focus {
    border-color: #e98006;
    box-shadow: 0 0 0 2px rgba(233, 128, 6, 0.25);
}

.bhajasi-search-clear {
    position: absolute;
    right: 12px;
    top: 50%;
    transform: translateY(-50%);
    background: transparent;
    border: none;
    color: #cbd5e1;
    cursor: pointer;
    font-size: 15px;
    padding: 4px;
    line-height: 1;
}

.bhajasi-search-clear:hover {
    color: #e98006;
}

.bhajasi-search-dropdown {
    position: absolute;
    top: calc(100% + 6px);
    left: 0;
    right: 0;
    z-index: 60;
    background: #1a2332;
    border: 1px solid #41436A;
    border-radius: 14px;
    box-shadow: 0 12px 35px rgba(0,0,0,.8);
    max-height: 380px;
    overflow-y: auto;
    padding: 6px;
}

.bhajasi-dropdown-item {
    display: flex;
    flex-direction: column;
    gap: 4px;
    width: 100%;
    text-align: left;
    background: transparent;
    border: none;
    border-bottom: 1px solid rgba(65, 67, 106, 0.4);
    padding: 10px 12px;
    color: #ffffff;
    cursor: pointer;
    border-radius: 8px;
    transition: background .2s;
}

.bhajasi-dropdown-item:last-child {
    border-bottom: none;
}

.bhajasi-dropdown-item:hover {
    background: rgba(65, 67, 106, 0.5);
}

.bhajasi-dropdown-title {
    font-family: 'Khand', sans-serif;
    font-size: 17px;
    font-weight: 600;
    color: #e98006;
    letter-spacing: 0.02em;
}

.bhajasi-dropdown-match {
    font-size: 12px;
    color: #cbd5e1;
    line-height: 1.5;
    font-family: 'Hind', sans-serif;
}

.bhajasi-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 10px;
}

.bhajasi-card {
    width: 100%;
    text-align: left;
    background: linear-gradient(145deg, #2a3950, #1c2738);
    border: 1px solid rgba(65, 67, 106, 0.8);
    border-radius: 15px;
    padding: 14px;
    cursor: pointer;
    color: #ffffff;
    transition: border-color .2s ease, transform .2s ease, background .2s ease;
}

.bhajasi-card:hover {
    border-color: #e98006;
    transform: translateY(-2px);
    background: linear-gradient(145deg, #324460, #222f44);
}

.bhajasi-card-title {
    font-family: 'Khand', sans-serif;
    font-size: 18px;
    font-weight: 600;
    line-height: 1.35;
    color: #ffffff;
    letter-spacing: 0.02em;
}

.bhajasi-card-sub {
    margin-top: 4px;
    color: #cbd5e1;
    font-size: 11px;
    line-height: 1.5;
    font-family: 'Noto Sans Devanagari', sans-serif;
}

.bhajasi-saint-card { min-height: 72px; }
.bhajasi-work-card { min-height: 76px; }
.bhajasi-theme-card { min-height: 70px; }

.bhajasi-empty {
    grid-column: 1 / -1;
    border: 1px dashed rgba(233, 128, 6, 0.35);
    border-radius: 14px;
    padding: 22px;
    color: #cbd5e1;
    text-align: center;
    font-size: 13.5px;
    background: rgba(26, 35, 50, 0.4);
}

.bhajasi-reader-head {
    padding: 1px 1px 14px;
}

.bhajasi-reader-nav {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    padding-bottom: 12px;
}

.bhajasi-back {
    border: 0;
    background: transparent;
    color: #e98006;
    padding: 0;
    cursor: pointer;
    font-size: 13px;
    font-weight: 600;
}

.bhajasi-day-label {
    color: #e98006;
    font-size: 12px;
    font-weight: 700;
    white-space: nowrap;
    font-family: 'Noto Sans Devanagari', sans-serif;
}

.bhajasi-title-row {
    display: flex;
    align-items: flex-end;
    justify-content: space-between;
    gap: 12px;
}

/* Reader Title: Tiro Devanagari Marathi */
.bhajasi-title {
    margin: 0;
    color: #ffffff;
    font-family: 'Tiro Devanagari Marathi', serif;
    font-size: 26px;
    line-height: 1.3;
    font-weight: 700;
    letter-spacing: 0.015em;
}

/* Verse Card */
.bhajasi-verse {
    position: relative;
    background: linear-gradient(155deg, #2a3950, #1b2535);
    border: 1px solid rgba(65, 67, 106, 0.7);
    border-radius: 16px;
    padding: 16px 14px 14px;
    margin: 12px 0;
    box-shadow: 0 4px 18px rgba(0,0,0,0.25);
}

.bhajasi-verse-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 10px;
    padding-bottom: 6px;
    border-bottom: 1px dashed rgba(255,255,255,0.08);
}

.bhajasi-verse-badge {
    font-size: 12px;
    font-weight: 700;
    color: #fcffcd;
    font-family: 'Tiro Devanagari Marathi', serif;
    letter-spacing: 0.03em;
}

.bhajasi-verse-wa-btn {
    border: 1px solid rgba(37, 211, 102, 0.45);
    background: rgba(37, 211, 102, 0.12);
    color: #25d366;
    border-radius: 99px;
    padding: 3px 9px;
    font-size: 10.5px;
    font-weight: 600;
    cursor: pointer;
    display: inline-flex;
    align-items: center;
    gap: 5px;
    transition: all 0.2s ease;
}

.bhajasi-verse-wa-btn:hover {
    background: #25d366;
    color: #ffffff;
    transform: scale(1.02);
}

/* Verse text font set to Laila Bold 700 */
.bhajasi-verse-text {
    color: #ffffff;
    text-align: center;
    font-family: 'Laila', serif;
    font-size: 18.5px;
    line-height: 1.85;
    font-weight: 700;
}

.bhajasi-verse-line {
    display: block;
    margin: 2px 0;
    padding: 0;
}

.bhajasi-meaning {
    border-top: 1px solid rgba(65, 67, 106, 0.6);
    margin-top: 12px;
    padding-top: 10px;
    text-align: left;
}

.bhajasi-meaning-title {
    font-family: 'Noto Serif Devanagari', serif;
    color: #a0ea90;
    font-size: 11.5px;
    font-weight: 700;
    margin-bottom: 4px;
    letter-spacing: 0.02em;
}

.bhajasi-meaning-text {
    margin: 0;
    color: #cbd5e1;
    font-family: 'Noto Sans Devanagari', sans-serif;
    font-size: 13.5px;
    line-height: 1.8;
    font-weight: 400;
}

.bhajasi-teaching {
    border-top: 1px dashed rgba(48, 197, 173, 0.35);
    margin-top: 10px;
    padding-top: 8px;
    text-align: left;
}

.bhajasi-teaching-title {
    font-family: 'Noto Serif Devanagari', serif;
    color: #30c5ad;
    font-size: 11.5px;
    font-weight: 700;
    margin-bottom: 3px;
    letter-spacing: 0.02em;
}

.bhajasi-teaching-text {
    margin: 0;
    color: #f1f5f9;
    font-family: 'Playpen Sans', 'Noto Sans Devanagari', cursive, sans-serif;
    font-size: 13px;
    line-height: 1.8;
    font-weight: 500;
}

.bhajasi-reader-footer {
    display: flex;
    justify-content: space-between;
    margin-top: 12px;
}

.bhajasi-pager {
    width: 44px;
    height: 44px;
    border: 1px solid rgba(65, 67, 106, 0.8);
    background: #1c2738;
    color: #e98006;
    border-radius: 12px;
    cursor: pointer;
    font-size: 15px;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: all 0.2s ease;
}

.bhajasi-pager:hover:not(:disabled) {
    border-color: #e98006;
    background: #41436A;
    color: #ffffff;
}

.bhajasi-pager:disabled {
    opacity: .25;
    cursor: default;
}

.bhajasi-continue-list {
    display: grid;
    gap: 8px;
}

.bhajasi-continue-card {
    width: 100%;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 10px;
    padding: 12px 14px;
    border: 1px solid rgba(65, 67, 106, 0.8);
    border-radius: 14px;
    background: linear-gradient(145deg, #2a3950, #1c2738);
    color: #ffffff;
    cursor: pointer;
    text-align: left;
    transition: all 0.2s ease;
}

.bhajasi-continue-card:hover {
    border-color: #e98006;
    transform: translateY(-1px);
}

.bhajasi-continue-main { min-width: 0; }
.bhajasi-continue-saint { color: #e98006; font-size: 10px; font-weight: 700; }
.bhajasi-continue-work { color: #ffffff; font-size: 15px; font-weight: 600; font-family: 'Khand', sans-serif; }
.bhajasi-continue-day { color: #cbd5e1; font-size: 10px; white-space: nowrap; }

/* Page Footer */
.bhajasi-page-footer {
    width: 100%;
    margin-top: 30px;
    padding: 16px 14px 22px;
    text-align: center;
    border-top: 1px solid rgba(233, 128, 6, 0.2);
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 8px;
}

.bhajasi-footer-inner {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    color: #e2e8f0;
    font-size: 12px;
    font-weight: 600;
    letter-spacing: 0.02em;
}

.bhajasi-footer-logo {
    width: 20px;
    height: 20px;
    object-fit: contain;
    border-radius: 50%;
}

.bhajasi-footer-sub {
    font-size: 10px;
    color: #94a3b8;
}

/* Bottom Navigation */
.bhajasi-bottom {
    position: fixed;
    z-index: 60;
    left: 50%;
    bottom: 0;
    transform: translateX(-50%);
    width: min(760px,100%);
    padding: 7px 14px calc(7px + env(safe-area-inset-bottom));
    background: rgba(26, 35, 50, 0.98);
    backdrop-filter: blur(14px);
    -webkit-backdrop-filter: blur(14px);
    border-top: 1px solid rgba(233, 128, 6, 0.2);
    display: flex;
    justify-content: space-around;
}

.bhajasi-bottom button {
    border: 0;
    background: transparent;
    color: #94a3b8;
    font-size: 10px;
    cursor: pointer;
}

.bhajasi-bottom button.active {
    color: #e98006;
    font-weight: 700;
}

.bhajasi-bottom-icon {
    display: block;
    font-size: 16px;
    margin-bottom: 2px;
}

@media (min-width: 600px) {
    .bhajasi-main { padding: 16px 25px 25px; }
    .bhajasi-grid { grid-template-columns: repeat(3, 1fr); }
    .bhajasi-verse { padding: 18px 20px 16px; }
    .bhajasi-verse-text { font-size: 20px; }
}

@media (max-width: 520px) {
    .bhajasi-brandline { gap: 6px; }
    .bhajasi-brand { font-size: 20px; line-height: 1.2; padding-top: 2px; }
    .bhajasi-tagline { font-size: 9px; }
    .bhajasi-header-logo { width: 34px; height: 34px; min-width: 34px; min-height: 34px; }
}


/* =========================================================
   NOTIFICATION CENTER
========================================================= */
.onesignal-bell-launcher-dialog {
    position: fixed;
    z-index: 200;
    inset: auto 14px 82px auto;
    width: min(360px, calc(100vw - 28px));
    padding: 18px;
    border: 1px solid rgba(233, 128, 6, 0.45);
    border-radius: 18px;
    background: #1a2332;
    color: #fff;
    box-shadow: 0 18px 50px rgba(0,0,0,.55);
}
.onesignal-bell-launcher-dialog::backdrop {
    background: rgba(0,0,0,.28);
}
.bhajasi-notify-card {
    display: flex;
    flex-direction: column;
    gap: 10px;
}
.bhajasi-notify-title {
    margin: 0;
    color: #e98006;
    font-family: 'Tiro Devanagari Marathi', serif;
    font-size: 20px;
}
.bhajasi-notify-text {
    margin: 0;
    color: #cbd5e1;
    font-size: 12.5px;
    line-height: 1.7;
}
.bhajasi-notify-actions {
    display: flex;
    gap: 8px;
    flex-wrap: wrap;
}
.bhajasi-notify-btn {
    border: 1px solid rgba(233,128,6,.4);
    border-radius: 10px;
    padding: 8px 12px;
    background: #41436A;
    color: #fff;
    cursor: pointer;
    font-weight: 600;
}
.bhajasi-notify-btn.primary {
    background: #e98006;
    color: #1a2332;
}
.bhajasi-notify-btn.ghost {
    background: transparent;
    color: #cbd5e1;
}
.bhajasi-notify-bell {
    position: fixed;
    right: 14px;
    bottom: 82px;
    z-index: 90;
    width: 44px;
    height: 44px;
    border-radius: 50%;
    border: 1px solid rgba(233,128,6,.55);
    background: #1a2332;
    color: #fbd52d;
    box-shadow: 0 8px 24px rgba(0,0,0,.35);
    cursor: pointer;
}
.bhajasi-nitya-card {
    border-color: rgba(251,213,45,.35);
    background: linear-gradient(145deg, #3b3544, #1c2738);
}
.bhajasi-loading-inline {
    color: #cbd5e1;
    font-size: 12px;
    padding: 8px 2px;
}
.bhajasi-meta {
    color: #94a3b8;
    font-size: 11px;
    line-height: 1.6;
}
.bhajasi-breadcrumb {
    display: flex;
    flex-wrap: wrap;
    gap: 5px;
    color: #94a3b8;
    font-size: 11px;
    margin-bottom: 8px;
}
.bhajasi-breadcrumb span:last-child { color: #e98006; }

body.script:
//

const SAINTS_BASE =
    'https://raw.githubusercontent.com/project-bharat/bhajasi/main/data/saints/';
const DATA_BASE =
    'https://raw.githubusercontent.com/project-bharat/bhajasi/main/data/';
const NITYA_BASE =
    DATA_BASE + 'nitya-pathan/';const SITE_URL =
    'https://bhajasibharat.blogspot.com/';
const SITE_LOGO =
    'https://blogger.googleusercontent.com/img/b/R29vZ2xl/AVvXsEg94LhEYUGaBU0HdY5Cumz3j-nmJ7NdDjBQ5DCKsZd5uBYDTKYFHgQGZ5Iik5cJoBJ2r4pntUVQDJVTI2SvvraMlgW0PVtCOcsx7ebdj2ILBLVEq-nPNy_sfukMA1GE7xfmr28iOBA3JfPy0BJNx08R_DaB6ncp6EFpkJ_o_IyAWZuD6QaTeN4BSMZ_cLkq/s1600/light%20bhajasi%20White%20Spiral%20Logo%20with%20Golden%20Dot.png';

const PROGRESS_KEY = 'bhajasi_reading_progress_v2';
const NOTIFY_KEY = 'bhajasi_notification_v1';

const {
    useState,
    useEffect,
    useMemo,
    useRef
} = React;

const CONTENT_KEYS = [
    'entries',
    'verses',
    'ovis',
    'abhangs',
    'shloks',
    'stanzas'
];

function safeJSON(value, fallback) {
    try {
        return JSON.parse(value);
    } catch (e) {
        return fallback;
    }
}

function readProgress() {
    return safeJSON(localStorage.getItem(PROGRESS_KEY) || '{}', {});
}

function writeProgress(key, value) {
    const old = readProgress();
    old[key] = Object.assign({}, old[key] || {}, value);
    localStorage.setItem(PROGRESS_KEY, JSON.stringify(old));
}

function slug(value) {
    return String(value || '')
        .trim()
        .toLowerCase()
        .replace(/\s+/g, '-')
        .replace(/[^\w\u0900-\u097F-]+/g, '')
        .replace(/-+/g, '-');
}

function makeWorkKey(saint, work) {
    return String(saint && saint.id || '') + '::' +
        String(work && (work.id || work.file || work.title) || '');
}

function toMarathiDigits(num) {
    if (num === null || num === undefined || num === '') return '';
    const digits = ['०','१','२','३','४','५','६','७','८','९'];
    return String(num).replace(/[0-9]/g, function(d) {
        return digits[d];
    });
}

function getVerseLabel(entry, index, work) {
    if (!entry) return '';
    if (entry.label || entry.typeLabel) {
        return entry.label || entry.typeLabel;
    }

    let value = '';
    if (entry.number !== undefined && entry.number !== null) {
        value = toMarathiDigits(entry.number);
    } else if (entry.id) {
        const match = String(entry.id).match(/(\d+)$/);
        if (match) value = toMarathiDigits(parseInt(match[1], 10));
    }
    if (!value) {
        const textMatch = String(entry.text || '').match(
            /॥\s*([०-९0-9]+(?:-[०-९0-9]+)?)\s*॥/u
        );
        if (textMatch) value = toMarathiDigits(textMatch[1]);
    }
    if (!value) value = toMarathiDigits(index + 1);

    const type = String(
        entry.type ||
        entry.kind ||
        (work && work.type) ||
        ''
    ).toLowerCase();

    if (
        type.indexOf('अभंग') >= 0 ||
        type.indexOf('abhang') >= 0
    ) {
        return 'अभंग ' + value;
    }

    if (
        type.indexOf('श्लोक') >= 0 ||
        type.indexOf('shlok') >= 0 ||
        type.indexOf('स्तोत्र') >= 0
    ) {
        return 'श्लोक ' + value;
    }

    if (
        type.indexOf('पद') >= 0 ||
        type.indexOf('pad') >= 0
    ) {
        return 'पद ' + value;
    }

    if (
        type.indexOf('दोहा') >= 0 ||
        type.indexOf('doha') >= 0
    ) {
        return 'दोहा ' + value;
    }

    if (
        type.indexOf('ओवी') >= 0 ||
        type.indexOf('ovi') >= 0 ||
        type.indexOf('ग्रंथ') >= 0
    ) {
        return 'ओवी ' + value;
    }

    return 'रचना ' + value;
}

function splitPoem(text) {
    if (!text) return [];
    const normalized = String(text)
        .replace(/\r\n/g, '\n')
        .trim();

    if (!normalized) return [];

    const lines = normalized
        .split('\n')
        .map(function(line) { return line.trim(); })
        .filter(Boolean);

    if (lines.length > 1) return lines;

    const clauses = normalized
        .split(/(?<=।)\s+/u)
        .map(function(x) { return x.trim(); })
        .filter(Boolean);

    if (clauses.length <= 2) return clauses;

    const grouped = [];
    for (let i = 0; i < clauses.length; i += 2) {
        grouped.push(
            clauses.slice(i, i + 2).join(' ')
        );
    }
    return grouped;
}

function normalizeContent(raw) {
    if (Array.isArray(raw)) {
        return {
            entries: raw,
            days: 1
        };
    }

    if (!raw || typeof raw !== 'object') {
        return {
            entries: [],
            days: 1
        };
    }

    let entries = [];
    CONTENT_KEYS.some(function(key) {
        if (Array.isArray(raw[key])) {
            entries = raw[key];
            return true;
        }
        return false;
    });

    if (!entries.length && Array.isArray(raw.content)) {
        entries = raw.content;
    }

    return Object.assign({}, raw, {
        entries: entries,
        days: Number(raw.days || 1)
    });
}

async function fetchJSON(url) {
    const response = await fetch(
        url + (url.indexOf('?') >= 0 ? '&' : '?') + 'v=' + Date.now(),
        {
            cache: 'no-store',
            headers: { 'Accept': 'application/json' }
        }
    );
    if (!response.ok) {
        throw new Error('HTTP ' + response.status + ': ' + url);
    }
    return response.json();
}

function resolveURL(kind, file) {
    if (!file) return '';
    if (/^https?:\/\//i.test(file)) return file;
    if (kind === 'nitya') return NITYA_BASE + file.replace(/^nitya-pathan\//, '');
    return SAINTS_BASE + file.replace(/^saints\//, '');
}

function workHasSections(work) {
    return !!(
        work &&
        Array.isArray(work.sections) &&
        work.sections.length
    );
}

function getWorkSummary(work) {
    if (!work) return '';
    if (work.description) return work.description;
    if (work.type) return work.type;
    if (work.days) return 'दिवस ' + toMarathiDigits(work.days);
    if (work.sections) {
        return toMarathiDigits(work.sections.length) + ' विभाग';
    }
    return '';
}

function formatSubTitle(title, parentTitle) {
    if (!title) return '';
    if (parentTitle && title.indexOf(parentTitle) === 0) {
        return title
            .replace(
                new RegExp(
                    '^' + parentTitle.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') +
                    '\\s*[-—–]?\\s*',
                    'u'
                ),
                ''
            )
            .trim() || title;
    }
    return title;
}

function flattenContentForSearch(content) {
    const data = normalizeContent(content);
    return data.entries.map(function(entry, index) {
        return {
            entry: entry,
            index: index,
            text: [
                entry.text,
                entry.meaning,
                entry.teaching,
                entry.commentary,
                entry.translation
            ].filter(Boolean).join(' ')
        };
    });
}

function entryBelongsToDay(entry, day) {
    if (entry.day === undefined || entry.day === null || entry.day === '') {
        return Number(day) === 1;
    }
    return Number(entry.day) === Number(day);
}

function getEntriesForDay(content, day) {
    const data = normalizeContent(content);
    if (!data.entries.length) return [];
    const hasDayData = data.entries.some(function(entry) {
        return entry.day !== undefined && entry.day !== null;
    });
    if (!hasDayData) return data.entries;
    return data.entries.filter(function(entry) {
        return entryBelongsToDay(entry, day);
    });
}

function getTotalDays(work, content) {
    const data = normalizeContent(content);
    const fromWork = Number(work && work.days || 0);
    const fromContent = Number(data.days || 0);
    const entryDays = data.entries
        .map(function(entry) { return Number(entry.day || 0); })
        .filter(Boolean);
    const fromEntries = entryDays.length
        ? Math.max.apply(Math, entryDays)
        : 1;
    return Math.max(1, fromWork, fromContent, fromEntries);
}

function expandHaripath(entries, workTitle) {
    const isHaripath = String(workTitle || '').indexOf('हरिपाठ') >= 0;
    if (!isHaripath) return entries || [];

    const expanded = [];
    (entries || []).forEach(function(entry, entryIndex) {
        const text = String(entry.text || '').trim();
        const matches = text.split(
            /(?=॥\s*[०-९0-9]+\s*॥)/u
        ).map(function(s) { return s.trim(); }).filter(Boolean);

        if (matches.length > 1) {
            matches.forEach(function(part, partIndex) {
                const numberMatch = part.match(
                    /॥\s*([०-९0-9]+)\s*॥/u
                );
                expanded.push(Object.assign({}, entry, {
                    id: String(entry.id || 'haripath-' + entryIndex) +
                        '-' + (partIndex + 1),
                    number: numberMatch ? numberMatch[1] : partIndex + 1,
                    text: part
                }));
            });
        } else {
            expanded.push(entry);
        }
    });
    return expanded;
}

function readNotifySettings() {
    return safeJSON(localStorage.getItem(NOTIFY_KEY) || '{}', {});
}

function saveNotifySettings(settings) {
    localStorage.setItem(
        NOTIFY_KEY,
        JSON.stringify(settings || {})
    );
}

function notificationSupported() {
    return 'Notification' in window;
}

function getDailyNityaIndex(length) {
    if (!length) return 0;
    const start = new Date(
        new Date().getFullYear(),
        0,
        0
    );
    const now = new Date();
    const dayOfYear = Math.floor(
        (now - start) / 86400000
    );
    return (dayOfYear - 1) % length;
}

function getProgressItems(saints) {
    const progress = readProgress();
    const result = [];

    (saints || []).forEach(function(saint) {
        (saint.works || []).forEach(function(work) {
            if (workHasSections(work)) {
                work.sections.forEach(function(section) {
                    const saved = progress[makeWorkKey(saint, section)];
                    if (saved) {
                        result.push({
                            saint: saint,
                            work: section,
                            parentWork: work,
                            day: Number(saved.day || 1),
                            updatedAt: Number(saved.updatedAt || 0)
                        });
                    }
                });
            } else {
                const saved = progress[makeWorkKey(saint, work)];
                if (saved) {
                    result.push({
                        saint: saint,
                        work: work,
                        parentWork: null,
                        day: Number(saved.day || 1),
                        updatedAt: Number(saved.updatedAt || 0)
                    });
                }
            }
        });
    });

    return result.sort(function(a, b) {
        return b.updatedAt - a.updatedAt;
    });
}

function topLevelWorks(saints) {
    return (saints || []).flatMap(function(saint) {
        return (saint.works || []).map(function(work, index) {
            return {
                saint: saint,
                work: work,
                index: index
            };
        });
    });
}

function buildMetadataSearch(saints, nitya) {
    const results = [];

    (saints || []).forEach(function(saint) {
        results.push({
            type: 'saint',
            title: saint.name || saint.id,
            sub: 'संत • ग्रंथसूची',
            saint: saint
        });

        (saint.works || []).forEach(function(work) {
            results.push({
                type: 'work',
                title: work.title || work.id,
                sub: [saint.name, work.type].filter(Boolean).join(' • '),
                saint: saint,
                work: work
            });

            (work.sections || []).forEach(function(section) {
                results.push({
                    type: 'section',
                    title: section.title || section.id,
                    sub: [work.title, saint.name].filter(Boolean).join(' • '),
                    saint: saint,
                    work: section,
                    parentWork: work
                });
            });
        });
    });

    ((nitya && nitya.works) || []).forEach(function(work) {
        results.push({
            type: 'nitya',
            title: work.title || work.id,
            sub: ['नित्य पठण', work.type].filter(Boolean).join(' • '),
            nityaWork: work
        });
    });

    return results;
}

function App() {
    const [saints, setSaints] = useState([]);
    const [nitya, setNitya] = useState(null);
    const [view, setView] = useState('home');
    const [selectedSaint, setSelectedSaint] = useState(null);
    const [selectedParentWork, setSelectedParentWork] = useState(null);
    const [selectedWork, setSelectedWork] = useState(null);
    const [selectedNityaWork, setSelectedNityaWork] = useState(null);
    const [selectedContent, setSelectedContent] = useState(null);
    const [day, setDay] = useState(1);
    const [search, setSearch] = useState('');
    const [searchResults, setSearchResults] = useState([]);
    const [searchLoading, setSearchLoading] = useState(false);
    const [theme, setTheme] = useState(null);
    const [loading, setLoading] = useState(true);
    const [workLoading, setWorkLoading] = useState(false);
    const [loadErrors, setLoadErrors] = useState([]);
    const [notifyOpen, setNotifyOpen] = useState(false);
    const [notifySettings, setNotifyState] = useState(readNotifySettings());
    const [navMeta, setNavMeta] = useState({ themes: {}, contentTypes: {}, granthGroups: [] });
    const [saintTypeFilter, setSaintTypeFilter] = useState(null);
    const [nityaTypeFilter, setNityaTypeFilter] = useState(null);
    const [granthFilter, setGranthFilter] = useState(null);
    const [searchOpen, setSearchOpen] = useState(false);
    const contentCache = useRef({});
    const touchStart = useRef(null);

    useEffect(function() {
        async function loadData() {
            const errors = [];

            try {
                const index = await fetchJSON(SAINTS_BASE + 'index.json');
                const files = Array.isArray(index)
                    ? index
                    : (index.saints || index.files || []);

                const results = await Promise.allSettled(
                    files.map(function(file) {
                        return fetchJSON(SAINTS_BASE + file);
                    })
                );

                results.forEach(function(result, indexPosition) {
                    if (result.status === 'fulfilled' &&
                        result.value &&
                        result.value.id) {
                        saints.push(result.value);
                    } else {
                        errors.push(
                            String(files[indexPosition] || 'unknown')
                        );
                    }
                });
            } catch (error) {
                console.error('Bhajasi saints index error:', error);
                errors.push('saints/index.json');
            }

            try {
                const nityaIndex = await fetchJSON(
                    DATA_BASE + 'nitya-pathan/index.json'
                );
                setNitya(nityaIndex);
            } catch (error) {
                console.error('Bhajasi nitya index error:', error);
                errors.push('nitya-pathan/index.json');
            }

            try {
                const navigation = await fetchJSON(DATA_BASE + 'navigation.json');
                setNavMeta(navigation || {});
            } catch (error) {
                console.error('Bhajasi navigation metadata error:', error);
            }

            setSaints(saints);
            setLoadErrors(errors);
            setLoading(false);
        }

        loadData();
    }, []);

    useEffect(function() {
        let pageTitle =
            'भजसी भारत .com — संतवाणी | सार्थ संतसाहित्य, हरिपाठ, ज्ञानेश्वरी व अभंग चिंतन';

        if (view === 'reader' && selectedWork && selectedSaint) {
            pageTitle =
                selectedWork.title +
                ' — ' +
                selectedSaint.name +
                ' | भजसी भारत .com';
        } else if (view === 'nityaReader' && selectedNityaWork) {
            pageTitle =
                selectedNityaWork.title +
                ' — नित्य पठण | भजसी भारत .com';
        } else if (view === 'works' && selectedSaint) {
            pageTitle =
                selectedSaint.name +
                ' — ग्रंथसूची | भजसी भारत .com';
        } else if (view === 'sections' && selectedParentWork) {
            pageTitle =
                selectedParentWork.title +
                ' — ' +
                selectedSaint.name +
                ' | भजसी भारत .com';
        } else if (view === 'theme' && theme) {
            pageTitle =
                theme.title +
                ' — संतवाणी चिंतन | भजसी भारत .com';
        } else if (view === 'nitya') {
            pageTitle =
                'नित्य पठण स्तोत्रे व मंत्र — भजसी भारत .com';
        }

        document.title = pageTitle;
    }, [
        view,
        selectedSaint,
        selectedParentWork,
        selectedWork,
        selectedNityaWork,
        day,
        theme
    ]);

    function navigate(nextView) {
        setView(nextView);
        window.scrollTo({ top: 0, behavior: 'smooth' });
    }

    function openSaint(saint) {
        setSelectedSaint(saint);
        setSelectedParentWork(null);
        setSelectedWork(null);
        setSelectedContent(null);
        navigate('works');
    }

    async function loadWorkContent(work, kind) {
        if (!work) return null;

        const file = work.file;
        if (!file) {
            return normalizeContent(work);
        }

        const url = resolveURL(kind || 'saint', file);
        if (contentCache.current[url]) {
            return contentCache.current[url];
        }

        const data = normalizeContent(await fetchJSON(url));
        contentCache.current[url] = data;
        return data;
    }

    async function openWork(
        saint,
        work,
        initialDay,
        parentWork,
        kind
    ) {
        if (!work) return;

        const targetKind = kind || 'saint';
        setWorkLoading(true);

        try {
            const content = await loadWorkContent(work, targetKind);
            const total = getTotalDays(work, content);
            const progress = readProgress();
            const saved = progress[makeWorkKey(saint || { id: targetKind }, work)];
            const requested = Number(
                initialDay ||
                (saved && saved.day) ||
                1
            );
            const safeDay = Math.min(
                Math.max(1, requested),
                total
            );

            if (targetKind === 'nitya') {
                setSelectedNityaWork(work);
                setSelectedContent(content);
                setSelectedWork(null);
                setSelectedSaint(null);
                setSelectedParentWork(null);
                setDay(safeDay);
                navigate('nityaReader');
            } else {
                setSelectedSaint(saint);
                setSelectedParentWork(parentWork || null);
                setSelectedWork(work);
                setSelectedContent(content);
                setSelectedNityaWork(null);
                setDay(safeDay);
                writeProgress(
                    makeWorkKey(saint, work),
                    {
                        day: safeDay,
                        updatedAt: Date.now()
                    }
                );
                navigate('reader');
            }
        } catch (error) {
            console.error('Bhajasi work loading error:', error);
            alert('हे साहित्य सध्या लोड करता आले नाही.');
        } finally {
            setWorkLoading(false);
        }
    }

    async function handleWorkClick(
        saint,
        work,
        parentWork
    ) {
        if (!work) return;

        if (workHasSections(work)) {
            setSelectedSaint(saint);
            setSelectedParentWork(work);
            setSelectedWork(null);
            setSelectedContent(null);
            navigate('sections');
            return;
        }

        await openWork(
            saint,
            work,
            1,
            parentWork || null,
            'saint'
        );
    }

    function openNityaList() {
        setSelectedNityaWork(null);
        setSelectedContent(null);
        navigate('nitya');
    }

    function goHome() {
        setSelectedSaint(null);
        setSelectedParentWork(null);
        setSelectedWork(null);
        setSelectedNityaWork(null);
        setSelectedContent(null);
        setTheme(null);
        navigate('home');
    }

    function goSaints() {
        setSelectedParentWork(null);
        navigate('saints');
    }

    function nextDay() {
        if (!selectedWork && !selectedNityaWork) return;
        const total = getTotalDays(
            selectedWork || selectedNityaWork,
            selectedContent
        );
        if (day >= total) return;

        const next = day + 1;
        setDay(next);

        if (selectedWork && selectedSaint) {
            writeProgress(
                makeWorkKey(selectedSaint, selectedWork),
                {
                    day: next,
                    updatedAt: Date.now()
                }
            );
        }
        window.scrollTo({ top: 0, behavior: 'smooth' });
    }

    function previousDay() {
        if (day <= 1) return;

        const previous = day - 1;
        setDay(previous);

        if (selectedWork && selectedSaint) {
            writeProgress(
                makeWorkKey(selectedSaint, selectedWork),
                {
                    day: previous,
                    updatedAt: Date.now()
                }
            );
        }
        window.scrollTo({ top: 0, behavior: 'smooth' });
    }

    function onTouchStart(event) {
        if (
            view !== 'reader' &&
            view !== 'nityaReader'
        ) return;
        touchStart.current =
            event.changedTouches[0].clientX;
    }

    function onTouchEnd(event) {
        if (
            (view !== 'reader' &&
             view !== 'nityaReader') ||
            touchStart.current === null
        ) return;

        const end = event.changedTouches[0].clientX;
        const distance = end - touchStart.current;

        if (Math.abs(distance) < 55) {
            touchStart.current = null;
            return;
        }

        if (distance < 0) nextDay();
        else previousDay();

        touchStart.current = null;
    }

    function handleShare() {
        const shareData = {
            title: 'भजसी भारत .com — संतवाणी',
            text:
                'संतसाहित्याचे शांत वाचन, सार्थ ज्ञानेश्वरी, हरिपाठ, गाथा आणि नित्य पठण.',
            url: SITE_URL
        };

        if (navigator.share) {
            navigator.share(shareData).catch(function() {});
            return;
        }

        if (navigator.clipboard) {
            navigator.clipboard.writeText(SITE_URL)
                .then(function() {
                    alert('भजसी भारत लिंक कॉपी झाली आहे.');
                })
                .catch(function() {
                    alert(SITE_URL);
                });
        } else {
            alert(SITE_URL);
        }
    }

    async function searchContent(query) {
        const q = String(query || '').trim().toLowerCase();

        if (q.length < 2) {
            setSearchResults([]);
            setSearchLoading(false);
            return;
        }

        const metadata = buildMetadataSearch(
            saints,
            nitya
        );

        const quick = metadata.filter(function(item) {
            return [
                item.title,
                item.sub,
                item.saint && item.saint.search,
                item.work && item.work.search,
                item.nityaWork && item.nityaWork.search
            ].filter(Boolean).join(' ').toLowerCase().indexOf(q) >= 0;
        }).slice(0, 20);

        setSearchResults(quick);
        setSearchLoading(true);

        const candidates = metadata.filter(function(item) {
            return (
                item.type === 'work' ||
                item.type === 'section' ||
                item.type === 'nitya'
            );
        });

        const contentMatches = [];

        await Promise.all(
            candidates.map(async function(item) {
                try {
                    const work =
                        item.work || item.nityaWork;
                    const kind =
                        item.type === 'nitya'
                            ? 'nitya'
                            : 'saint';

                    const content =
                        await loadWorkContent(
                            work,
                            kind
                        );

                    flattenContentForSearch(content)
                        .forEach(function(found) {
                            if (
                                found.text &&
                                found.text.toLowerCase().indexOf(q) >= 0
                            ) {
                                contentMatches.push({
                                    type: 'verse',
                                    title:
                                        (item.title || work.title) +
                                        ' • ' +
                                        getVerseLabel(
                                            found.entry,
                                            found.index
                                        ),
                                    sub:
                                        String(found.entry.text || '')
                                            .replace(/\s+/g, ' ')
                                            .slice(0, 100),
                                    saint:
                                        item.saint || null,
                                    work: work,
                                    parentWork:
                                        item.parentWork || null,
                                    nityaWork:
                                        item.nityaWork || null,
                                    day:
                                        Number(found.entry.day || 1)
                                });
                            }
                        });
                } catch (error) {
                    /* One unavailable content file must not break search. */
                }
            })
        );

        const combined = quick.concat(contentMatches);
        const seen = {};
        const unique = combined.filter(function(item) {
            const key =
                item.type + '::' +
                item.title + '::' +
                item.sub;
            if (seen[key]) return false;
            seen[key] = true;
            return true;
        });

        setSearchResults(unique.slice(0, 30));
        setSearchLoading(false);
    }

    useEffect(function() {
        const timer = setTimeout(function() {
            searchContent(search);
        }, 350);

        return function() {
            clearTimeout(timer);
        };
    }, [search, saints, nitya]);

    function activateSearchResult(item) {
        setSearch('');

        if (item.type === 'saint') {
            openSaint(item.saint);
            return;
        }

        if (item.type === 'work') {
            handleWorkClick(
                item.saint,
                item.work,
                null
            );
            return;
        }

        if (item.type === 'section') {
            handleWorkClick(
                item.saint,
                item.work,
                item.parentWork
            );
            return;
        }

        if (item.type === 'nitya') {
            openWork(
                null,
                item.nityaWork,
                1,
                null,
                'nitya'
            );
            return;
        }

        if (item.type === 'verse') {
            if (item.nityaWork) {
                openWork(
                    null,
                    item.nityaWork,
                    item.day,
                    null,
                    'nitya'
                );
            } else {
                openWork(
                    item.saint,
                    item.work,
                    item.day,
                    item.parentWork || null,
                    'saint'
                );
            }
        }
    }

    const filteredSaints = useMemo(function() {
        const q = search.trim().toLowerCase();
        if (!q || q.length < 2) return saints;

        return saints.filter(function(saint) {
            return [
                saint.name,                saint.search,
                (saint.works || []).map(function(work) {
                    return [
                        work.title,
                        work.type,
                        work.description,
                        work.search
                    ].filter(Boolean).join(' ');
                }).join(' ')
            ].filter(Boolean).join(' ').toLowerCase().indexOf(q) >= 0;
        });
    }, [saints, search]);

    const continueItems = useMemo(
        function() {
            return getProgressItems(saints);
        },
        [saints, selectedContent, view]
    );

    const themeTitles = Object.keys(navMeta.themes || {});
    const themes = (themeTitles.length ? themeTitles : ['नामस्मरण', 'भक्ती', 'ज्ञान', 'समता', 'सेवा', 'वैराग्य', 'सदाचार', 'मनःशांती']).map(function(title) {
        return { title: title, keys: [title] };
    });

    const saintTypeFilters = ['ओवी', 'अभंग', 'श्लोक', 'पद', 'दोहा', 'रचना'];
    const nityaTypeFilters = ['स्तोत्र', 'श्लोक', 'सूक्त', 'मंत्र', 'संध्या', 'चालीसा'];
    const granthGroups = navMeta.granthGroups || [];

    const saintTypeSaints = useMemo(function() {
        if (!saintTypeFilter) return saints;
        const mapping = navMeta.contentTypes || {};
        return saints.filter(function(saint) {
            return (saint.works || []).some(function(work) {
                const types = mapping[saint.id] && mapping[saint.id][work.id]
                    ? mapping[saint.id][work.id]
                    : (work.contentTypes || []);
                return types.indexOf(saintTypeFilter) >= 0 || (
                    saintTypeFilter === 'ओवी' && /ओवी|हरिपाठ|ज्ञानेश्वरी|दासबोध|भागवत|रामायण|ग्रामगीता/.test((work.type || '') + ' ' + (work.title || ''))
                ) || (
                    saintTypeFilter === 'अभंग' && /अभंग|गाथा|हरिपाठ/.test((work.type || '') + ' ' + (work.title || ''))
                ) || (
                    saintTypeFilter === 'श्लोक' && /श्लोक/.test((work.type || '') + ' ' + (work.title || ''))
                ) || (
                    saintTypeFilter === 'पद' && /पद/.test((work.type || '') + ' ' + (work.title || ''))
                ) || (
                    saintTypeFilter === 'दोहा' && /दोहा|साखी/.test((work.type || '') + ' ' + (work.title || ''))
                );
            });
        });
    }, [saints, saintTypeFilter, navMeta.contentTypes]);

    const filteredNityaWorks = useMemo(function() {
        if (!nityaTypeFilter) return nityaWorks;
        return nityaWorks.filter(function(work) {
            return String(work.type || '').indexOf(nityaTypeFilter) >= 0;
        });
    }, [nityaWorks, nityaTypeFilter]);

    const filteredGranthWorks = useMemo(function() {
        if (!granthFilter) return topLevelWorks(saints);
        const group = granthGroups.find(function(item) { return item.id === granthFilter; });
        if (!group) return topLevelWorks(saints);
        return topLevelWorks(saints.filter(function(saint) {
            return group.saints.indexOf(saint.id) >= 0;
        }));
    }, [saints, granthFilter, granthGroups]);

    const themeMatches = useMemo(function() {
        if (!theme) return [];
        const pairs = (navMeta.themes && navMeta.themes[theme.title]) || [];
        return pairs.map(function(pair) {
            const saint = saints.find(function(item) { return item.id === pair[0]; });
            const work = saint && (saint.works || []).find(function(item) { return item.id === pair[1]; });
            return saint && work ? {
                saint: saint,
                work: work,
                parentWork: null,
                displayTitle: work.title,
                displaySub: saint.name
            } : null;
        }).filter(Boolean);
    }, [saints, theme, navMeta.themes]);

    window.__bhajasiSelectedSaint = selectedSaint;
    window.__bhajasiSelectedWork = selectedWork || selectedNityaWork;

    const currentEntries = useMemo(function() {
        if (!selectedContent) return [];

        const raw = getEntriesForDay(
            selectedContent,
            day
        );

        return expandHaripath(
            raw,
            selectedWork
                ? selectedWork.title
                : selectedNityaWork
                    ? selectedNityaWork.title
                    : ''
        );
    }, [
        selectedContent,
        day,
        selectedWork,
        selectedNityaWork
    ]);

    const totalDays = getTotalDays(
        selectedWork || selectedNityaWork,
        selectedContent
    );

    const progressPercent =
        totalDays <= 1
            ? 100
            : ((day - 1) / (totalDays - 1)) * 100;

    async function requestNotifications() {
        if (!notificationSupported()) {
            alert(
                'या ब्राउझरमध्ये सूचना उपलब्ध नाहीत.'
            );
            return;
        }

        try {
            const permission =
                await Notification.requestPermission();

            if (permission === 'granted') {
                const settings = {
                    enabled: true,
                    permission: permission,
                    lastNotifiedDate:
                        readNotifySettings().lastNotifiedDate || ''
                };

                saveNotifySettings(settings);
                setNotifyState(settings);
                setNotifyOpen(false);

                maybeSendDailyNotification(
                    settings,
                    true
                );
            } else {
                const settings = {
                    enabled: false,
                    permission: permission
                };
                saveNotifySettings(settings);
                setNotifyState(settings);
            }
        } catch (error) {
            console.error(
                'Notification permission error:',
                error
            );
        }
    }

    function disableNotifications() {
        const settings = Object.assign(
            {},
            readNotifySettings(),
            { enabled: false }
        );
        saveNotifySettings(settings);
        setNotifyState(settings);
        setNotifyOpen(false);
    }

    function notificationMessage() {
        const progressItems =
            getProgressItems(saints);

        if (progressItems.length) {
            const item = progressItems[0];
            return {
                title: 'भजसी भारत — वाचन पुढे सुरू ठेवा',
                body:
                    item.work.title +
                    ' — दिवस ' +
                    toMarathiDigits(item.day) +
                    ' पासून वाचन पुढे सुरू करा.'
            };
        }

        const works =
            nitya && Array.isArray(nitya.works)
                ? nitya.works
                : [];

        if (works.length) {
            const index =
                getDailyNityaIndex(works.length);
            const work = works[index];

            return {
                title: 'आजचे नित्य पठण',
                body:
                    (work.title || 'आजचे पठण') +
                    ' आजच्या शांत वाचनासाठी उघडा.'
            };
        }

        return {
            title: 'भजसी भारत',
            body:
                'आज थोडा वेळ संतसाहित्याच्या शांत वाचनासाठी द्या.'
        };
    }

    function maybeSendDailyNotification(
        settings,
        force
    ) {
        if (
            !notificationSupported() ||
            Notification.permission !== 'granted' ||
            !settings ||
            !settings.enabled
        ) return;

        const today =
            new Date().toISOString().slice(0, 10);

        if (!force && settings.lastNotifiedDate === today) {
            return;
        }

        const message = notificationMessage();

        try {
            new Notification(
                message.title,
                {
                    body: message.body,
                    icon: SITE_LOGO,
                    tag: 'bhajasi-daily-reading'
                }
            );

            const next = Object.assign(
                {},
                settings,
                { lastNotifiedDate: today }
            );
            saveNotifySettings(next);
            setNotifyState(next);
        } catch (error) {
            console.error(
                'Browser notification error:',
                error
            );
        }
    }

    useEffect(function() {
        if (!notificationSupported()) return;

        const settings =
            readNotifySettings();

        setNotifyState(settings);

        const timer =
            setTimeout(function() {
                maybeSendDailyNotification(
                    settings,
                    false
                );
            }, 2500);

        const dailyCheck =
            setInterval(function() {
                maybeSendDailyNotification(
                    readNotifySettings(),
                    false
                );
            }, 60000);

        return function() {
            clearTimeout(timer);
            clearInterval(dailyCheck);
        };
    }, [saints, nitya]);

    function renderPageNav(items) {
        return (
            <div className='bhajasi-page-nav'>
                {items.map(function(item) {
                    return (
                        <button key={item.label} className='bhajasi-nav-chip' onClick={item.onClick}>
                            {item.label}
                        </button>
                    );
                })}
            </div>
        );
    }

    function renderFilters(items, active, setActive) {
        return (
            <div className='bhajasi-filter-grid'>
                {items.map(function(item) {
                    return (
                        <button key={item} className={'bhajasi-filter-chip' + (active === item ? ' active' : '')} onClick={function() { setActive(active === item ? null : item); }}>
                            {item}
                        </button>
                    );
                })}
            </div>
        );
    }

    function renderGlobalSearchUI() {
        return (
            <>
                <button className='bhajasi-floating-search' aria-label='संपूर्ण साहित्य शोधा' title='संपूर्ण साहित्य शोधा' onClick={function() { setSearchOpen(true); }}>
                    <i className='fa-solid fa-magnifying-glass'></i>
                </button>
                {searchOpen && (
                    <div className='bhajasi-search-overlay' onMouseDown={function(event) {
                        if (event.target === event.currentTarget) {
                            setSearchOpen(false);
                            setSearch('');
                        }
                    }}>
                        <div className='bhajasi-search-dialog'>
                            <div className='bhajasi-global-search-head'>
                                <input
                                    autoFocus
                                    className='bhajasi-global-search-input'
                                    value={search}
                                    onChange={function(event) { setSearch(event.target.value); }}
                                    placeholder='संत, ग्रंथ, अध्याय, ओवी, अभंग, श्लोक, अर्थ किंवा शिकवण शोधा…'
                                    autoComplete='off'
                                />
                                <button className='bhajasi-global-search-close' onClick={function() { setSearchOpen(false); setSearch(''); }}>
                                    <i className='fa-solid fa-xmark'></i>
                                </button>
                            </div>
                            <div className='bhajasi-global-results'>
                                {!search.trim() ? (
                                    <div className='bhajasi-global-empty'>संपूर्ण संतसाहित्य, ग्रंथ आणि नित्य पठण शोधा.</div>
                                ) : (
                                    <>
                                        {searchResults.map(function(item, index) {
                                            return (
                                                <button key={item.type + '-' + index} className='bhajasi-global-result' onClick={function() { activateSearchResult(item); setSearchOpen(false); }}>
                                                    <div className='bhajasi-global-result-title'>{item.title}</div>
                                                    <div className='bhajasi-global-result-sub'>{item.sub}</div>
                                                </button>
                                            );
                                        })}
                                        {searchLoading && <div className='bhajasi-global-empty'>संपूर्ण साहित्यामधील शोध सुरू आहे…</div>}
                                        {!searchLoading && searchResults.length === 0 && <div className='bhajasi-global-empty'>संबंधित साहित्य सापडले नाही.</div>}
                                    </>
                                )}
                            </div>
                        </div>
                    </div>
                )}
            </>
        );
    }

    function renderPageFooter() {
        return (
            <footer className='bhajasi-page-footer'>
                <div className='bhajasi-footer-inner'>
                    <img
                        src={SITE_LOGO}
                        alt='भजसी भारत'
                        className='bhajasi-footer-logo'
                    />
                    <span>
                        निर्मिती आणि संकलन: भरत रासवे
                    </span>
                </div>
                <span className='bhajasi-footer-sub'>
                    भजसी भारत .com — मराठी संतसाहित्याचे डिजिटल व्यासपीठ
                </span>
            </footer>
        );
    }

    function renderNotificationUI() {
        const enabled =
            notifySettings &&
            notifySettings.enabled &&
            notificationSupported() &&
            Notification.permission === 'granted';

        return (
            <>
                <button
                    className='bhajasi-notify-bell'
                    title='सूचना व्यवस्थापित करा'
                    aria-label='सूचना व्यवस्थापित करा'
                    onClick={function() {
                        setNotifyOpen(true);
                    }}
                >
                    <i className='fa-regular fa-bell'></i>
                </button>

                {notifyOpen && (
                    <div
                        className='onesignal-bell-launcher-dialog'
                        id='onesignal-bell-dialog'
                        popover='auto'
                    >
                        <div className='bhajasi-notify-card'>
                            <h3 className='bhajasi-notify-title'>
                                वाचन सूचना
                            </h3>

                            <p className='bhajasi-notify-text'>
                                तुम्ही जिथे वाचन थांबवले आहे तिथून पुढे सुरू करण्याची
                                आठवण किंवा दररोज नित्य पठणातील साहित्याची सूचना
                                ब्राउझरद्वारे मिळवा.
                            </p>

                            {!notificationSupported() ? (
                                <p className='bhajasi-notify-text'>
                                    या ब्राउझरमध्ये Notification API उपलब्ध नाही.
                                </p>
                            ) : (
                                <>
                                    <p className='bhajasi-notify-text'>
                                        स्थिती:{' '}
                                        {enabled
                                            ? 'सूचना सुरू आहेत'
                                            : Notification.permission === 'denied'
                                                ? 'ब्राउझरने सूचना नाकारल्या आहेत'
                                                : 'सूचना बंद आहेत'}
                                    </p>

                                    <div className='bhajasi-notify-actions'>
                                        {!enabled && (
                                            <button
                                                className='bhajasi-notify-btn primary'
                                                onClick={requestNotifications}
                                            >
                                                सूचना सुरू करा
                                            </button>
                                        )}

                                        {enabled && (
                                            <button
                                                className='bhajasi-notify-btn'
                                                onClick={function() {
                                                    maybeSendDailyNotification(
                                                        readNotifySettings(),
                                                        true
                                                    );
                                                    setNotifyOpen(false);
                                                }}
                                            >
                                                आजची सूचना पाठवा
                                            </button>
                                        )}

                                        {enabled && (
                                            <button
                                                className='bhajasi-notify-btn ghost'
                                                onClick={disableNotifications}
                                            >
                                                बंद करा
                                            </button>
                                        )}

                                        <button
                                            className='bhajasi-notify-btn ghost'
                                            onClick={function() {
                                                setNotifyOpen(false);
                                            }}
                                        >
                                            बंद
                                        </button>
                                    </div>

                                    <p className='bhajasi-notify-text'>
                                        टीप: हे browser Notification API वापरते.
                                        पूर्णपणे बंद असलेल्या ब्राउझरमध्ये हमखास
                                        दैनिक background push साठी स्वतंत्र
                                        Web Push / OneSignal service worker
                                        आवश्यक आहे.
                                    </p>
                                </>
                            )}
                        </div>
                    </div>
                )}
            </>
        );
    }

    if (loading) {
        return (
            <div className='bhajasi-root'>
                <div className='bhajasi-app'>
                    <header className='bhajasi-header'>
                        <div className='bhajasi-brandline'>
                            <div className='bhajasi-brand-container'>
                                <img
                                    src={SITE_LOGO}
                                    alt='भजसी भारत लोगो'
                                    className='bhajasi-header-logo'
                                />
                                <div className='bhajasi-brand-group'>
                                    <div className='bhajasi-brand-wrapper'>
                                        <h1 className='bhajasi-brand'>
                                            भजसी भारत
                                        </h1>
                                        <span className='brand-domain'>
                                            .com
                                        </span>
                                    </div>
                                    <span className='bhajasi-tagline'>
                                        संतवाणी • अभंग • हरिनाम • चिंतन
                                    </span>
                                </div>
                            </div>
                        </div>
                    </header>
                    <main className='bhajasi-main'>
                        <div className='bhajasi-empty'>
                            संतसाहित्य आणि नित्य पठण लोड होत आहे…
                        </div>
                    </main>
                </div>
            </div>
        );
    }

    const nityaWorks =
        nitya && Array.isArray(nitya.works)
            ? nitya.works
            : [];

    return (
        <div
            className='bhajasi-root'
            onTouchStart={onTouchStart}
            onTouchEnd={onTouchEnd}
        >
            <div className='bhajasi-app'>

                <header className='bhajasi-header'>
                    <div className='bhajasi-brandline'>
                        <div
                            className='bhajasi-brand-container'
                            onClick={goHome}
                            style={{ cursor: 'pointer' }}
                        >
                            <img
                                src={SITE_LOGO}
