                            <div className='bhajasi-grid'>
                                {themeMatches.length === 0 ? (
                                    <div className='bhajasi-empty'>
                                        या विषयाशी संबंधित साहित्य
                                        उपलब्ध नाही.
                                    </div>
                                ) : (
                                    themeMatches.map(function(item, index) {
                                        return (
                                            <button
                                                key={
                                                    (item.work.id ||
                                                     item.work.file ||
                                                     item.displayTitle) +
                                                    '-' +
                                                    index
                                                }
                                                className='bhajasi-card'
                                                onClick={function() {
                                                    handleWorkClick(
                                                        item.saint,
                                                        item.work,
                                                        item.parentWork
                                                    );
                                                }}
                                            >
                                                <div className='bhajasi-card-title'>
                                                    {item.displayTitle}
                                                </div>
                                                <div className='bhajasi-card-sub'>
                                                    {item.displaySub}
                                                </div>
                                            </button>
                                        );
                                    })
                                )}
                            </div>
                        </section>
                    )}

                    {loadErrors.length > 0 && (
                        <div className='bhajasi-empty' style={{ marginTop: '18px' }}>
                            काही डेटा फाइल्स लोड करता आल्या नाहीत. कृपया पुन्हा प्रयत्न करा.
                        </div>
                    )}

                    {renderPageFooter()}
                </main>

                <nav className='bhajasi-bottom'>
                    <button
                        className={
                            view === 'home' ? 'active' : ''
                        }
                        onClick={goHome}
                    >
                        <span className='bhajasi-bottom-icon'>
                            <i className='fa-solid fa-house'></i>
                        </span>
                        मुख्य
                    </button>

                    <button
                        className={
                            view === 'saints' ||
                            view === 'works' ||
                            view === 'sections'
                                ? 'active'
                                : ''
                        }
                        onClick={goSaints}
                    >
                        <span className='bhajasi-bottom-icon'>
                            <i className='fa-solid fa-hands-praying'></i>
                        </span>
                        संत
                    </button>

                    <button
                        className={view === 'granth' ? 'active' : ''}
                        onClick={function() { setGranthFilter(null); navigate('granth'); }}
                    >
                        <span className='bhajasi-bottom-icon'><i className='fa-solid fa-book'></i></span>
                        ग्रंथ
                    </button>

                    <button
                        className={
                            view === 'nitya' ||
                            view === 'nityaReader'
                                ? 'active'
                                : ''
                        }
                        onClick={openNityaList}
                    >
                        <span className='bhajasi-bottom-icon'>
                            <i className='fa-solid fa-book-open'></i>
                        </span>
                        नित्य पठण
                    </button>
                </nav>

                {renderGlobalSearchUI()}
            </div>
        </div>
    );
}

/* =========================================================
   IMAGE SHARE — kept compatible with the previous frontend
========================================================= */
async function shareVerseSnap(entry, index) {
    const saintTitle =
        window.__bhajasiSelectedSaint &&
        window.__bhajasiSelectedSaint.name
            ? window.__bhajasiSelectedSaint.name
            : 'संतवाणी';

    const workTitle =
        window.__bhajasiSelectedWork &&
        window.__bhajasiSelectedWork.title
            ? window.__bhajasiSelectedWork.title
            : '';

    const lines = splitPoem(entry.text || '');
    const label = getVerseLabel(entry, index, selectedWork || selectedNityaWork);
    const width = 1080;
    const padding = 70;
    const contentWidth = width - padding * 2;

    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d');

    function wrap(text, font) {
        if (!text) return [];
        ctx.font = font;
        const words = String(text).split(' ');
        const result = [];
        let current = '';

        words.forEach(function(word) {
            const candidate =
                current ? current + ' ' + word : word;

            if (
                ctx.measureText(candidate).width >
                contentWidth
            ) {
                if (current) result.push(current);
                current = word;
            } else {
                current = candidate;
            }
        });

        if (current) result.push(current);
        return result;
    }

    const meaning =
        wrap(
            entry.meaning ||
            entry.arth ||
            entry.translation ||
            '',
            '400 28px "Noto Sans Devanagari", sans-serif'
        );

    const teaching =
        wrap(
            entry.teaching ||
            entry.shikavan ||
            entry.lesson ||
            '',
            '500 28px "Playpen Sans", cursive, sans-serif'
        );

    const height = Math.max(
        1200,
        300 +
        lines.length * 64 +
        (meaning.length ? 130 + meaning.length * 46 : 0) +
        (teaching.length ? 130 + teaching.length * 46 : 0) +
        180
    );

    canvas.width = width;
    canvas.height = height;

    const gradient =
        ctx.createLinearGradient(0, 0, width, height);
    gradient.addColorStop(0, '#2a3950');
    gradient.addColorStop(0.5, '#1e2838');
    gradient.addColorStop(1, '#151d2a');

    ctx.fillStyle = gradient;
    ctx.fillRect(0, 0, width, height);

    ctx.strokeStyle = 'rgba(233,128,6,.45)';
    ctx.lineWidth = 3;
    ctx.beginPath();

    if (ctx.roundRect) {
        ctx.roundRect(
            30,
            30,
            width - 60,
            height - 60,
            24
        );
    } else {
        ctx.rect(30, 30, width - 60, height - 60);
    }

    ctx.stroke();

    ctx.textAlign = 'center';
    ctx.fillStyle = '#e98006';
    ctx.font =
        '700 36px "Tiro Devanagari Marathi", serif';
    ctx.fillText(
        saintTitle + ' • ' + workTitle,
        width / 2,
        95
    );

    ctx.fillStyle = '#fcffcd';
    ctx.font =
        '600 25px "Noto Sans Devanagari", sans-serif';
    ctx.fillText(
        label,
        width / 2,
        140
    );

    let y = 225;

    ctx.fillStyle = '#ffffff';
    ctx.font =
        '700 40px "Laila", serif';

    lines.forEach(function(line) {
        ctx.fillText(line, width / 2, y);
        y += 64;
    });

    if (meaning.length) {
        y += 30;
        ctx.fillStyle = '#a0ea90';
        ctx.font =
            '700 23px "Noto Serif Devanagari", serif';
        ctx.fillText('भावार्थ', width / 2, y);
        y += 48;

        ctx.textAlign = 'left';
        ctx.fillStyle = '#cbd5e1';
        ctx.font =
            '400 28px "Noto Sans Devanagari", sans-serif';

        meaning.forEach(function(line) {
            ctx.fillText(line, padding, y);
            y += 46;
        });
    }

    if (teaching.length) {
        y += 25;
        ctx.textAlign = 'center';
        ctx.fillStyle = '#30c5ad';
        ctx.font =
            '700 23px "Noto Serif Devanagari", serif';
        ctx.fillText('शिकवण', width / 2, y);
        y += 48;

        ctx.textAlign = 'left';
        ctx.fillStyle = '#f1f5f9';
        ctx.font =
            '500 28px "Playpen Sans", cursive, sans-serif';

        teaching.forEach(function(line) {
            ctx.fillText(line, padding, y);
            y += 46;
        });
    }

    ctx.textAlign = 'center';
    ctx.fillStyle = '#e98006';
    ctx.font =
        '600 22px "Noto Sans Devanagari", sans-serif';
    ctx.fillText(
        'भजसी भारत .com',
        width / 2,
        height - 105
    );

    ctx.fillStyle = '#94a3b8';
    ctx.font =
        '400 18px "Noto Sans Devanagari", sans-serif';
    ctx.fillText(
        'निर्मिती आणि संकलन: भरत रासवे',
        width / 2,
        height - 72
    );

    canvas.toBlob(async function(blob) {
        if (!blob) return;

        const file =
            new File(
                [blob],
                'bhajasi-verse.png',
                { type: 'image/png' }
            );

        const shareText =
            saintTitle +
            ' • ' +
            workTitle +
            ' • ' +
            label +
            '\n\n' +
            SITE_URL;

        if (
            navigator.canShare &&
            navigator.canShare({ files: [file] })
        ) {
            try {
                await navigator.share({
                    title: 'भजसी भारत',
                    text: shareText,
                    files: [file]
                });
                return;
            } catch (error) {
                /* User cancelled or sharing unavailable. */
            }
        }

        const url = URL.createObjectURL(blob);
        const anchor = document.createElement('a');
        anchor.href = url;
        anchor.download = 'bhajasi-verse.png';
        document.body.appendChild(anchor);
        anchor.click();
        anchor.remove();

        setTimeout(function() {
            URL.revokeObjectURL(url);
        }, 1000);
    }, 'image/png');
}

ReactDOM.createRoot(
    document.getElementById('bhajasi-root')
).render(<App />);

